'use strict';
const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cases = Array.from({length:12}, (_,i)=>({id:`C${String(i+1).padStart(2,'0')}`,title:['会议最后确定了哪一天发布？','团队对风险提出了哪些应对办法？','这一阶段由谁负责复核？','后续行动包括什么？'][i%4],meeting:['A','B','C'][Math.floor(i/4)]}));
const initialState = task => ({task,panel:'context',expanded:false,nav:false,connected:true,agent:'ready',plan:false,selected:new Set(cases.map(c=>c.id)),custom:false,selectionDraft:null,job:'none',generated:0,scored:0,result:false,review:'unknown',reason:'',saved:false,change:'none',validation:'none',effect:'',cause:'',conclusionSaved:false,attachments:[],messages:[],draft:'',history:[],past:null});
const taskStates = {investigate:initialState('investigate'),baseline:initialState('baseline')};
let state = taskStates.investigate;
const taskNames={investigate:'调查会议总结中的决定遗漏',baseline:'评测当前版本'};
const jobName=()=>({none:'尚未提交',queued:'排队中',running:'运行中',cancel_requested:'取消已请求',cancelled:'已取消',completed:'执行已结束',reconciling:'执行端待核对'}[state.job]);
const btn=(label,action,kind='',attrs='')=>`<button data-action="${action}" class="${kind}" ${attrs}>${label}</button>`;
function notify(text){$('#notice').textContent=text;$('#notice').style.display='block';clearTimeout(notify.timer);notify.timer=setTimeout(()=>{$('#notice').style.display='none';},4500);}
function dialog(title,body,actions=btn('关闭','close-dialog')){$('#dialog').innerHTML=`<h2 id="dialog-title">${title}</h2>${body}<div class="dialog-actions">${actions}</div>`;$('#dialog').showModal();}
function event(title,kind,payload){state.history.push({title,kind,payload:structuredClone(payload),time:`演示事件 ${state.history.length+1}`});}
function openPanel(panel){state.panel=panel;state.past=null;render();}
function card(title,status,body,actions){return `<section class="work-card"><div class="card-head"><strong>${title}</strong><span class="badge">${status}</span></div><div class="card-body">${body}</div>${actions?`<div class="card-actions">${actions}</div>`:''}</section>`;}
function folded(title,body){return `<details class="folded"><summary>${title}</summary><div class="folded-body">${body}</div></details>`;}
function planCard(){return card('评测计划 · 当前 SN 版本',state.job==='none'?'草稿':'已冻结',`<div class="field-grid"><div><div class="label">任务与范围</div>QMSum · ${state.selected.size} 题 · ${new Set(cases.filter(c=>state.selected.has(c.id)).map(c=>c.meeting)).size} 场会议</div><div><div class="label">资料</div>所属会议完整资料，不按题裁剪</div><div><div class="label">执行与评分</div>chunk · 官方 Perl ROUGE</div><div><div class="label">源码</div>src-demo-base · clean 快照</div></div><div class="callout">构造配置：sn-profile-a / eval-profile-a。费用、调用数和耗时未测，均为未知。Agent 仅可提议；本演示由你提交。</div>`,btn('查看题单','questions')+btn('提交评测','submit','primary',state.job!=='none'||state.selected.size===0?'disabled':''));}
function progressCard(){const g=state.generated,s=state.scored;return card('评测作业 · job-demo',jobName(),`<div class="progress-row"><div class="progress-caption"><span>回答生成</span><span>${g} / ${state.selected.size}</span></div><div class="progress-track"><div class="progress-fill" style="width:${100*g/state.selected.size}%"></div></div></div><div class="progress-row"><div class="progress-caption"><span>官方评分</span><span>${s} / ${state.selected.size}</span></div><div class="progress-track"><div class="progress-fill scoring" style="width:${100*s/state.selected.size}%"></div></div></div><div class="hint">${state.job==='completed'?'已保存 11 份回答与 1 个空回答。空回答的有效零分保留，正式指标分母为 12。':'答案和评分分别保存；浏览器或 Agent 断连不取消作业。当前结果为阶段快照。'}</div>${state.job==='cancel_requested'?'<div class="callout">等待执行端确认。已生成内容保留，未开始项不补零。</div>':''}${state.job==='cancelled'?'<div class="callout">构造执行端已确认停止。只保留阶段输出，不显示完整成绩。</div>':''}<div class="demo-controls"><span>仅用于演示状态</span>${btn(state.custom?'演示：范围仅排队':'演示：推进一阶段','advance','',state.custom||!state.connected||!['queued','running'].includes(state.job)?'disabled':'')}${btn('页面断连／恢复','connection')}${state.job==='cancel_requested'?btn('演示：确认停止','ack-cancel','',!state.connected?'disabled':''):''}</div>`,btn('查看已有输出','partial')+btn('请求取消作业','cancel','',!['queued','running'].includes(state.job)?'disabled':''));}
function resultCard(){return card('结果 · 基线 scores-demo-base','官方评分完整',`<div class="numbers"><div><div class="number-value">0.352</div><div class="number-caption">ROUGE-L · Average_F</div></div><div><div class="number-value">12 / 12</div><div class="number-caption">正式评分范围</div></div></div><p>第 1 题值得调查：回答没有给出会议最终确定的日期。</p><div class="hint">这是构造案例。问题是否成立由人核对；官方分数与人评分别保存。QMSum 批量汇总不由浏览器逐题平均。</div>`,btn('查看完整成绩','scores')+btn('打开第 1 题证据','evidence','primary'));}
function investigationCard(){return card('调查线索 · 上下文选择','候选假设',`<p>构造检索记录包含最终决定，但保存的完整合成上下文没有该发言。先核对内容选择与去重映射。</p><div class="callout"><b>替代解释</b><br>阶段记录或去重映射可能不完整。检索命中不证明其最终应被采用，gold 也不是有效证据的穷举。</div><div class="hint">没有原生 span；这里只引用已有阶段快照。${state.saved?'你已保存一份独立的人评记录。':'尚无人评确认，不登记为根因。'}</div>`,btn('查看支持与限制','evidence')+btn('记录改动范围','authorize','primary'));}
function changeCard(){return card('改动与验证 · ChangeSet-demo',state.change==='proposed'?'改动已应用 · 未冻结':'构造源码已冻结',`<p>在上下文选择中保留最终决定候选。Changes 中可读实际改动摘要；这是手写 diff 示意。</p><div class="field-grid"><div><div class="label">基线</div>src-demo-base</div><div><div class="label">改后源码</div>${state.change==='frozen'?'src-demo-fix · 构造执行树':'dirty · 尚无稳定执行树'}</div><div><div class="label">验证题单</div>同一固定 12 题</div><div><div class="label">检查项</div>决定覆盖、额外样本、输入 token</div></div><div class="callout">${state.change==='proposed'?'当前 runner 拒绝 tracked dirty 源码。正式实现需捕获完整源码并物化执行树；不能直接提交当前目录。':'这里演示后续源码捕获能力：12 题来源与实际加载版本均为构造，不能据此称真实运行绑定已通过。'}</div>${state.change==='proposed'?`<div class="demo-controls"><span>后续能力示意</span>${btn('演示：完成源码捕获与绑定','freeze')}</div>`:''}`,btn('查看 Changes','changes')+btn('提交构造验证','validate','primary',state.change!=='frozen'||state.validation!=='none'?'disabled':''));}
function comparisonCard(){return card('验证结果 · 验证前后','需要人工结论',`<div class="numbers"><div><div class="number-value">0.352 → 0.381</div><div class="number-caption">完整固定 12 题 ROUGE-L</div></div></div><p>4 个诊断案例改善，8 个额外样本略降；输入 token 增加 18%。整体上升与局部取舍同时存在。</p><div class="hint">以上全为构造。没有显著性或全量推广结论。数值差分与原因假设分别判断。</div>`,btn('打开完整比较与双结论','compare','primary'));}
function mainBody(){let text=`<div class="message"><div class="speaker">任务目标</div><p>${state.task==='baseline'?'核对当前版本在固定题单上的正式成绩、覆盖与运行可靠性，再决定是否调查。':'定位总结为何遗漏最终决定，保留反例和额外样本。先取得正式成绩，再沿证据调查与验证。'}</p></div>`;
for(const m of state.messages)text+=`<div class="message user-message"><div class="speaker">你 · 演示输入</div><p>${esc(m)}</p></div>`;
if(!state.plan)text+=`<div class="message"><div class="speaker">Agent · 构造示例</div><p>我可以先拟定一份 QMSum 评测计划。你可以直接选题，也可以阅读已有材料。右侧保留当前任务的版本与协作范围。</p>${btn('提议固定 12 题计划','propose','primary')}</div>`;
if(state.plan)text+=state.job==='none'?planCard():folded(`已提交计划 · QMSum ${state.selected.size} 题`,planCard());
if(state.job!=='none')text+=['completed','cancelled'].includes(state.job)?folded(`评测作业 · ${jobName()} · 生成 ${state.generated} / ${state.selected.size} · 评分 ${state.scored} / ${state.selected.size}`,progressCard()):progressCard();
if(state.result)text+=state.change==='none'?resultCard()+investigationCard():folded('基线正式结果与调查依据',resultCard()+investigationCard());
if(state.change!=='none')text+=state.validation==='completed'?folded('改动来源与固定验证方案',changeCard()):changeCard();
if(state.validation==='running')text+=card('验证作业 · job-demo-validation','运行中','<p>独立作业、同一 12 题，引用构造改后源码。关闭 Agent 不终止此作业。</p><div class="demo-controls">'+btn('演示：完成验证','finish-validation')+'</div>',btn('查看固定验证范围','changes'));
if(state.validation==='completed')text+=comparisonCard();
return text;}
function materialHeader(){const tabs=['context','files','changes','scores','evidence','history'];const names={context:'任务',files:'Files',changes:'Changes',scores:'成绩',evidence:'证据',history:'历史'};return `<div class="material-head"><div class="header-row"><strong>${state.past?'固定历史记录':state.panel==='settings'?'设置与资源':'当前任务材料'}</strong><div>${btn(state.expanded?'收窄':'展开','expand','text-button')}${btn('关闭','hide-panel','text-button')}</div></div><div class="material-tabs">${tabs.map(p=>btn(names[p],'panel',p===state.panel?'current':'',`data-panel="${p}"`)).join('')}</div></div>`;}
function scoresMaterial(result){return `<h2>正式成绩</h2><div class="source">QMSum · 自定义固定 12 题 · 3 场会议<br>构造来源：${result==='fixed'?'scores-demo-fix':'scores-demo-base'} · src@demo</div><div class="table-scroll"><table><thead><tr><th>指标</th><th>Average_F</th><th>评分范围</th></tr></thead><tbody><tr><td>ROUGE-1</td><td class="num">${result==='fixed'?'0.438':'0.420'}</td><td>12 / 12</td></tr><tr><td>ROUGE-2</td><td class="num">${result==='fixed'?'0.189':'0.180'}</td><td>12 / 12</td></tr><tr><td>ROUGE-L</td><td class="num">${result==='fixed'?'0.381':'0.352'}</td><td>12 / 12</td></tr></tbody></table></div><div class="callout">使用正式批量输出的设计示意。有效零分与缺失有区别；此表没有真实工件，不是 SN 成绩。</div><h3>覆盖与边界</h3><p>计划 12；成功回答 11；空回答 1；正式评分 12。费用和延迟未采集，保持未知。没有跨 benchmark 总分。</p>${btn('引用该结果到输入框','attach-result','',`data-result="${result==='fixed'?'fix':'base'}"`)}`;}
function evidenceMaterial(){return `<h2>案例 C01 · 最终发布日期</h2><div class="source">构造答案 answer-demo-base · scores-demo-base<br>所有正文手写示意；不是真实 QMSum 内容</div><div class="stage">问题</div><p>会议最后确定了哪一天发布？</p><div class="stage">实际回答</div><div class="evidence-block">团队讨论了周五发布，但最终时间尚未确定。</div><div class="stage">源资料 · 节选，完整性已标注</div><div class="evidence-block">“我们最后定在周五发布。负责人会在今天更新计划。”</div><div class="stage">保存的检索记录 · 完整示意</div><p>包含这段最终决定。</p><div class="stage">实际合成上下文 · 完整示意</div><p>只包含前面的讨论，未包含最终决定发言。阶段映射尚需核查。</p><div class="callout">原生调用：未采集。不能从这些片段构造完整 Agent 调用树。gold 非有效证据的穷举。</div>${btn('将此案例作为上下文','attach-case')}<div class="review-form"><h3>你的判断</h3><label for="review">这个遗漏是否成立？</label><select id="review">${[['unknown','无法判断'],['confirmed','问题成立'],['rejected','不支持该问题']].map(([v,l])=>`<option value="${v}" ${state.review===v?'selected':''}>${l}</option>`).join('')}</select><label for="reason">理由与证据</label><textarea id="reason" placeholder="记录你看到的依据和限制">${esc(state.reason)}</textarea>${btn('保存演示判断','save-review','primary')}<p class="hint" id="review-receipt">${state.saved?'已生成本页内的固定演示修订，原分数未改变。':'仅保存在本页内存，没有服务器持久化回执。'}</p></div>`;}
function changesMaterial(){if(state.change==='none')return `<h2>Changes</h2><p>当前基线没有演示改动。</p><div class="hint">授权范围确定后才展示本次 Agent 改动；用户原有 dirty 内容应另行保留。</div>`;return `<h2>上下文选择改动</h2><div class="source">SN 目录 · 构造代码示意，非实际文件<br>src-demo-base → ${state.change==='frozen'?'src-demo-fix':'未冻结 dirty 内容'}</div><ul class="file-list"><li>M · context_selection.py（构造位置）</li></ul><pre><span class="removed">- candidates = rank_and_trim(passages, budget)</span><span class="added">+ candidates = preserve_decisions(passages, budget)</span></pre><p>假设：保留决定发言会减少遗漏。仍需排除映射问题与其他内容退化；这段伪代码不代表生产补丁。</p><div class="callout">${state.change==='frozen'?'已用演示控件模拟生成稳定执行树。真实捕获和加载核验尚未实现。':'改动已应用示意；尚不能交给只接受 clean 源码的当前 runner。'}</div><h3>验证方案</h3><p>固定同一 12 题，模型、提示和 scorer 不变。检查 4 个诊断案例与 8 个额外样本；输入 token 与延迟保持可见。</p><p class="hint">否定条件：源码修改未改善决定覆盖，或新增退化无法接受。比较通过不自动支持原因假设。</p>${btn('引用改动到输入框','attach-change')}`;}
function compareMaterial(){return `<h2>完整固定范围比较</h2><div class="source">同一自定义 12 题、scorer、模型及输入资料。构造比较器结果。</div><table><thead><tr><th>指标</th><th>基线</th><th>改后</th></tr></thead><tbody><tr><td>ROUGE-L</td><td class="num">0.352</td><td class="num">0.381</td></tr><tr><td>正式评分</td><td class="num">12 / 12</td><td class="num">12 / 12</td></tr></tbody></table><h3 style="margin-top:22px">附加样本视图与代价</h3><p>4 个诊断案例改善；8 个额外样本略降。该视图没有替代完整主表。</p><p>输入 token ＋18%；费用与延迟未知。无统计显著性结论。</p><div class="review-form"><label for="effect">效果结论</label><select id="effect">${[['','请选择'],['tradeoff','有改善，也有取舍'],['none','未观察到改善'],['unknown','证据不足']].map(([v,l])=>`<option value="${v}" ${state.effect===v?'selected':''}>${l}</option>`).join('')}</select><label for="cause">原因假设</label><select id="cause">${[['','请选择'],['unknown','仍未决'],['supported','得到支持'],['refuted','被反证']].map(([v,l])=>`<option value="${v}" ${state.cause===v?'selected':''}>${l}</option>`).join('')}</select>${btn('保存双结论','save-conclusion','primary')}<p class="hint">${state.conclusionSaved?'本页演示记录已保存，不代表服务端回执。':'模型解释是候选假设，人评不覆写官方分数。'}</p></div>`;}
function historyMaterial(){if(state.past){const e=state.history[state.past-1];return `<div class="snapshot">正在查看过去的固定记录 · ${e.time}<br>新结果不会覆盖该快照。</div><h2>${esc(e.title)}</h2>${e.kind==='result'?scoresMaterial(e.payload.result):`<pre>${esc(JSON.stringify(e.payload,null,2))}</pre>`}${btn('返回历史列表','history')}`;}return `<h2>任务历史</h2><p class="hint">只保存本页演示事件，不是实际持久历史。</p>${state.history.length?state.history.map((e,i)=>`<div class="history-row"><div class="time">${e.time} · ${e.kind}</div>${btn(esc(e.title),'past','',`data-index="${i+1}"`)}</div>`).join(''):'<div class="empty">尚无演示记录。提交计划后开始积累。</div>'}`;}
function settingsMaterial(){return `<h2>设置与资源</h2><div class="settings-section"><h3>Benchmark 目录</h3><table><thead><tr><th>套件</th><th>主要任务</th></tr></thead><tbody><tr><td>QASPER</td><td>答案 / 证据</td></tr><tr><td>MultiHop-RAG</td><td>多跳 QA / 检索</td></tr><tr><td>ALCE</td><td>ASQA / ELI5 / QAMPARI</td></tr><tr><td>QMSum</td><td>查询式会议总结</td></tr><tr><td>HotpotQA</td><td>答案 / supporting facts</td></tr></tbody></table><p class="hint">目录与协议在资源区。选题仍在任务内直接进入。ASQA 100 题与 948 题不混用；不因有套件目录就声称所有配置已就绪。</p></div><div class="settings-section"><h3>Agent 与执行接入</h3><p>构造 provider · Agent-demo<br>SN：src-demo-base / sn-profile-a<br>分析：只读 analyst，与编码 Agent 分开</p><p class="hint">实际接入采用 Paseo 公共 SDK。不能据此原型判断 provider 在线、已认证或具备工具权限。</p></div>`;}
function questionMaterial(){return `<h2>固定题单</h2><div class="hint">QMSum 构造 12 题。逐题选择保留在计划草稿；提交后不可改。搜索与跨页选择的生产行为见设计说明。</div><p><b>${state.selected.size}</b> 题已选 · 所属完整会议资料保留</p>${cases.map(c=>`<label class="question-option"><input type="checkbox" data-case="${c.id}" ${state.selected.has(c.id)?'checked':''} ${state.job!=='none'?'disabled':''}><span>${c.id} · 会议 ${c.meeting}<br>${c.title}</span></label>`).join('')}<div class="callout">任意非空自选范围可提交到排队示意。全流程演示使用独立固定 12 题计划，不能为自选范围生成虚假成绩。</div>${btn('使用固定 12 题演示计划','demo-plan','',state.job!=='none'?'disabled':'')}${state.selectionDraft!==null?btn('恢复之前的自选草稿','restore-selection','',state.job!=='none'?'disabled':''):''}`;}
function materialBody(){switch(state.panel){case'questions':return questionMaterial();case'scores':return state.result?scoresMaterial('base'):'<h2>正式成绩尚不可用</h2><p>运行快照不冒充正式汇总。</p>';case'evidence':return state.result?evidenceMaterial():'<h2>案例材料</h2><p>尚无已完成结果。可以先制定评测计划。</p>';case'changes':return changesMaterial();case'compare':return state.validation==='completed'?compareMaterial():'<h2>暂无可用比较</h2>';case'history':return historyMaterial();case'settings':return settingsMaterial();case'files':return '<h2>SN Files</h2><div class="source">目录为构造 worktree，不读取本机文件</div><ul class="file-list"><li>▸ backend/</li><li>　 context_selection.py（示意）</li><li>▸ docs/</li><li>　 architecture.md（示意）</li></ul><p class="hint">正式文件面板仅访问登记的 SN 根目录。密钥、运行数据及正式工件不因浏览文件获得写权限。</p>';case'partial':return `<h2>阶段输出</h2><p>已保存 ${state.generated} 个生成终态；评分 ${state.scored} 个。${state.result?'已有正式结果。':'尚无完整正式成绩。'}</p><p class="hint">取消或部分执行不会补齐未开始题，也不推算全量分数。</p>`;default:return `<h2>目标与协作范围</h2><p>${taskNames[state.task]}</p><div class="stage">SN workspace</div><p>sn-context-fix · 示例 worktree<br>src-demo-base · clean 源码快照</p><div class="stage">实际运行绑定</div><p>基线独立新进程（构造）。只用当前分支名不能确认运行版本。</p><div class="stage">协作</div><p>Agent-demo · 辅助模式<br>提议计划和调查，手动提交。改码须另行明确范围。</p><div class="callout">Agent 与作业独立。停止会话、关闭材料面板，不取消评测。提交、合并与部署不在默认闭环。</div>${btn('查看资源与配置','settings')}`;}}
function render(){const focusId=document.activeElement?.id;const oldScroll=$('.thread')?.scrollTop??0;$('#app').innerHTML=`<div class="shell ${!state.panel?'no-material':''} ${state.expanded?'expanded':''} ${state.nav?'show-nav':''}"><aside class="sidebar"><div class="brand">Silicon Notebook<small>评测与改进</small></div><div class="nav-label">WORKSPACES</div><div class="workspace">▾ sn-context-fix<small>worktree · fix/context-selection</small></div>${Object.entries(taskNames).map(([id,title])=>btn(`<span class="dot ${state.job==='running'?'active':''}"></span>${title}`,'task',`task-link ${id===state.task?'selected':''}`,`data-task="${id}"`)).join('')}<div class="workspace" style="margin-top:17px">▸ SN main<small>示例目录 · 只读入口</small></div><div class="nav-bottom">${btn('任务历史','history','text-button')}${btn('设置与资源','settings','text-button')}<div class="hint" style="padding:12px">单服务器 · 构造演示</div></div></aside><main class="main"><header class="task-header"><div class="eyebrow">sn-context-fix / 持续任务</div><div class="header-row"><h1>${taskNames[state.task]}</h1>${btn('☰','nav','mini-nav text-button','aria-label="打开 workspace 导航"')}</div><div class="meta"><span>${state.change==='proposed'?'有未提交改动':state.change==='frozen'?'改后构造快照已冻结':'src-demo-base · clean'}</span><span>运行绑定：${state.change==='proposed'?'未核对':'构造示意'}</span>${btn('查看','context','text-button')}</div><div class="header-actions">${btn('选题评测','questions')}${btn('查看结果','scores')}${btn('查看文件与改动','files')}</div><div class="current-step"><span>${state.validation==='completed'?'验证完成 · 待人工双结论':state.validation==='running'?'正在验证改动':state.change==='proposed'?'源码未冻结 · 先核对执行绑定':state.change==='frozen'?'验证计划可提交':state.result?'正式结果可读 · 调查证据':state.job!=='none'?jobName()+' · 生成 '+state.generated+' / '+state.selected.size+' · 评分 '+state.scored+' / '+state.selected.size:'尚无评测作业 · 制定范围'}</span>${btn('查看当前步骤','latest','text-button')}</div></header><div class="agent-strip"><span class="dot ${state.agent==='ready'?'active':''}"></span><span>Agent-demo · ${state.agent==='ready'?'可协作':'会话已中断示意'}</span>${state.agent==='ready'?btn('中断 Agent','interrupt','text-button'):btn('恢复演示会话','resume','text-button')}<span style="margin-left:auto" class="${state.connected?'':'warning'}">${state.connected?'页面快照：演示当前':'页面断连 · 保留旧快照'}</span></div><div class="thread"><div class="thread-content">${mainBody()}</div></div><footer class="composer"><div class="composer-box"><div class="attachments">${state.attachments.map((a,i)=>`<span class="attachment">${esc(a)} ${btn('×','remove-attachment','',`data-index="${i}" aria-label="移除附件"`)}</span>`).join('')}</div><label for="message" class="hidden">发给 Agent 的消息</label><textarea id="message" placeholder="让 Agent 帮助评测、调查或制定验证计划…">${esc(state.draft)}</textarea><div class="composer-actions"><div>${btn('＋上下文','attach')}${btn('选题','questions','text-button')}</div>${btn('发送演示输入','send','primary',state.agent!=='ready'?'disabled':'')}</div></div><div class="composer-note">本页不会调用 Agent。消息只记录为演示输入；正式卡片来自受管理对象。</div></footer></main>${state.panel?`<aside class="material" aria-label="任务材料">${materialHeader()}<div class="material-content">${materialBody()}</div></aside>`:''}</div>`;if($('.thread'))$('.thread').scrollTop=oldScroll;if(focusId==='message')$('#message')?.focus();}
function submit(){if(!state.selected.size){notify('至少选择一道题。');return;}if(state.job!=='none'){notify('已有提交；重复请求返回同一演示作业。');return;}dialog('提交这份评测计划？',`<p>QMSum · ${state.selected.size} 题 · chunk · 官方 ROUGE</p><p>源码 src-demo-base，完整所属会议资料。费用与调用数未知。</p><p class="hint">这是构造提交，没有真实服务器或模型请求。自选题单只演示排队。</p>`,btn('保留草稿','close-dialog')+btn('确认演示提交','confirm-submit','primary'));}
const actions={
 latest:()=>{const node=$('.thread-content .work-card:last-of-type')||$('.thread-content');node?.scrollIntoView({behavior:'smooth',block:'start'});},
 resume:()=>{state.agent='ready';render();notify('恢复构造会话；不改变原有 Job。');},
 'close-dialog':()=>$('#dialog').close(),guide:()=>dialog('评审新版任务工作面','<p>先点“提议固定 12 题计划”，看计划和选题；提交后用虚线演示控件推进生成与评分。打开成绩／证据并保存判断，再记录改动范围，查看 Changes 和源码冻结限制，演示验证与双结论。</p><p>左侧切换持续目标，右侧材料按需展开。页面断连和中断 Agent 不改变作业；历史打开当时固定记录。所有操作仅在本页内存，刷新重置。</p>'),
 propose:()=>{state.plan=true;render();},questions:()=>{state.plan=true;openPanel('questions');},'demo-plan':()=>{if(state.selectionDraft===null)state.selectionDraft=[...state.selected];state.selected=new Set(cases.map(c=>c.id));state.custom=false;render();notify('已打开固定 12 题演示计划，原自选草稿已保留。');},'restore-selection':()=>{state.selected=new Set(state.selectionDraft);state.selectionDraft=null;render();notify('已恢复之前的自选题单。');},submit,
 'confirm-submit':()=>{$('#dialog').close();state.plan=true;state.job='queued';state.custom=state.selected.size!==12;event('提交固定评测计划','plan',{caseIds:[...state.selected],source:'src-demo-base',mode:'chunk'});render();},
 advance:()=>{if(state.custom||!['queued','running'].includes(state.job))return;if(state.job==='queued'){state.job='running';state.generated=4;}else if(state.generated<12){state.generated=12;}else if(state.scored<8){state.scored=8;}else{state.scored=12;state.job='completed';state.result=true;event('基线正式结果 · 固定 12 题','result',{result:'base',coverage:12});}render();},
 connection:()=>{state.connected=!state.connected;render();notify(state.connected?'演示页面恢复；不改变作业执行事实。':'演示页面断连；保留最后快照，作业状态不变。');},
 cancel:()=>dialog('请求取消当前评测？','<p>停止后续派发，已保存答案和评分保留。执行端确认之前仅显示取消请求。</p>',btn('继续评测','close-dialog')+btn('登记演示取消请求','confirm-cancel','primary')),
 'confirm-cancel':()=>{$('#dialog').close();state.job='cancel_requested';event('登记取消请求','job',{status:state.job,generated:state.generated,scored:state.scored});render();},'ack-cancel':()=>{state.job='cancelled';event('执行端确认取消','job',{status:state.job,generated:state.generated,scored:state.scored});render();},
 interrupt:()=>dialog('中断 Agent 会话？','<p>只中断当前 Agent，评测或验证 Job 不受影响。正式实现需等待真实 provider／CLI 回执，本页仅模拟。</p>',btn('继续会话','close-dialog')+btn('模拟中断会话','confirm-interrupt','primary')),
 'confirm-interrupt':()=>{$('#dialog').close();state.agent='stopped';event('Agent 会话中断示意','session',{agent:'stopped',jobUnchanged:state.job});render();},
 partial:()=>openPanel('partial'),scores:()=>openPanel('scores'),evidence:()=>openPanel('evidence'),changes:()=>openPanel('changes'),files:()=>openPanel('files'),context:()=>openPanel('context'),history:()=>openPanel('history'),settings:()=>openPanel('settings'),compare:()=>openPanel('compare'),
 panel:el=>openPanel(el.dataset.panel),'hide-panel':()=>{state.panel=null;render();},expand:()=>{state.expanded=!state.expanded;render();},nav:()=>{state.nav=!state.nav;render();},task:el=>{state=taskStates[el.dataset.task];state.panel='context';state.nav=false;render();notify('已切换持续任务；计划、输入、作业和历史各自独立。');},
 'save-review':()=>{state.saved=true;event('C01 人评修订','review',{caseId:'C01',answer:'answer-demo-base',judgment:state.review,reason:state.reason});render();notify('仅保存在本页，官方分数未改变。');},
 authorize:()=>dialog('明确改动与验证范围','<p>构造委托：上下文选择模块；保留已有改动；固定 12 题验证；模型／提示／评分不变。</p><p>默认建议独立 worktree。若复用当前目录，需要明确已有 dirty 来源。停止条件：范围越界、写入者未知、源码不稳定或预算不足。</p><p class="hint">此按钮只建立手写改动示意，不运行 Agent、不编辑任何真实文件，也不提交或部署。</p>',btn('先调查','close-dialog')+btn('演示已按范围修改','confirm-change','primary')),
 'confirm-change':()=>{$('#dialog').close();state.change='proposed';event('SN 改动应用示意 · 未冻结','change',{source:'dirty',scope:'上下文选择',published:false});openPanel('changes');},freeze:()=>{state.change='frozen';event('源码捕获与运行绑定示意','source',{source:'src-demo-fix',verified:'constructed-only'});render();},
 validate:()=>{if(state.change!=='frozen')return;state.validation='running';event('固定 12 题验证提交示意','validation',{source:'src-demo-fix',cases:12});render();},'finish-validation':()=>{state.validation='completed';event('改后正式结果 · 固定 12 题','result',{result:'fixed',coverage:12});render();},
 'save-conclusion':()=>{if(!state.effect||!state.cause){notify('分别选择效果结论与原因假设。');return;}state.conclusionSaved=true;event('验证效果与原因双结论','review',{effect:state.effect,cause:state.cause});render();notify('演示双结论已保存；没有部署操作。');},past:el=>{state.past=Number(el.dataset.index);state.panel='history';render();},
 attach:()=>dialog('添加已核验的上下文对象',`<p>附件引用固定对象，不自动把完整正文或私有结果包送给模型。</p>`,btn('题单','attach-selection')+btn('结果','attach-result','',!state.result?'disabled':'')+btn('案例 C01','attach-case','',!state.result?'disabled':'')+btn('关闭','close-dialog')),
 'attach-selection':()=>addAttachment(`题单 · ${state.selected.size} 题`),'attach-result':el=>{if(state.result)addAttachment('结果 · scores-demo-'+(el?.dataset.result==='fix'?'fix':'base'));},'attach-case':()=>{if(state.result)addAttachment('案例 C01 · answer-demo-base');},'attach-change':()=>addAttachment('改动 · ChangeSet-demo'),'remove-attachment':el=>{state.attachments.splice(Number(el.dataset.index),1);render();},
 send:()=>{const text=state.draft.trim();if(!text)return;state.messages.push(text+(state.attachments.length?' [附：'+state.attachments.join('、')+']':''));state.draft='';state.attachments=[];render();notify('已记录演示输入；没有 Agent 推理。');}
};
function addAttachment(text){if(!state.attachments.includes(text))state.attachments.push(text);if($('#dialog').open)$('#dialog').close();render();}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el&&!el.disabled){const writes=['advance','ack-cancel','propose','submit','confirm-submit','cancel','confirm-cancel','interrupt','confirm-interrupt','resume','save-review','authorize','confirm-change','validate','save-conclusion','send'];if(!state.connected&&writes.includes(el.dataset.action)){notify('页面离线：保留输入，恢复连接后再提交。');return;}actions[el.dataset.action]?.(el);}});
document.addEventListener('input',e=>{if(e.target.id==='message')state.draft=e.target.value;if(e.target.id==='reason'){state.reason=e.target.value;state.saved=false;if($('#review-receipt'))$('#review-receipt').textContent='理由已修改，尚未保存；没有服务器持久化回执。';}});
document.addEventListener('change',e=>{if(e.target.dataset.case){if(e.target.checked)state.selected.add(e.target.dataset.case);else state.selected.delete(e.target.dataset.case);render();}if(e.target.id==='review'){state.review=e.target.value;state.saved=false;if($('#review-receipt'))$('#review-receipt').textContent='判断已修改，尚未保存。';}if(e.target.id==='effect')state.effect=e.target.value;if(e.target.id==='cause')state.cause=e.target.value;});
render();
